import openpyxl

wb = openpyxl.load_workbook('/root/data/test-rar.xlsx')
ws_total_reserves = wb['Total Reserves']

# Check all countries in Total Reserves that have 2025 data
countries_with_2025_tr = {}

for col in range(3, 16):
    date_info = ws_total_reserves.cell(row=3, column=col).value
    country = ws_total_reserves.cell(row=1, column=col).value

    if not country or not date_info:
        break

    if '2025' in str(date_info):
        value = ws_total_reserves.cell(row=17, column=col).value

        # Extract country name
        country_name = str(country).split(':')[0].strip() if ':' in str(country) else str(country)

        countries_with_2025_tr[country_name] = {
            'col': col,
            'value': value
        }
        print(f"2025: {country_name}: {value}")

print(f"\nTotal countries with 2025 Total Reserves data: {len(countries_with_2025_tr)}")

# Countries we selected for STEP 2:
step2_countries = ['Belarus', 'Georgia', 'Kazakhstan', 'Ukraine', 'Uzbekistan', 'Czechia', 'Latvia', 'Lithuania', 'Slovakia']

print("\nWhich STEP 2 countries have 2025 Total Reserves data:")
for country in step2_countries:
    if country in countries_with_2025_tr:
        print(f"  ✓ {country}")
    else:
        print(f"  ✗ {country} (REMOVE FROM STEP 3)")

